class Order {
  customer: Customer;
  items: Item[];

  customerAddress(): string {
    return `${this.customer.street}, ${this.customer.city}`;
  }
}

class Customer {
  street: string;
  city: string;
}

class PricingService {
  calculateFinalPrice(product: Product, qty: number) {
    return product.basePrice * qty * (1 - product.discountRate);
  }
}

class Product {
  basePrice: number;
  discountRate: number;
}

// Version A
class Customer {
  orders: Order[];
  loyaltyPoints(): number {
    return this.orders.reduce((s, o) => s + o.pointsEarned(), 0);
  }
}

// Version B
class Order {
  customer: Customer;
  pointsEarned(): number {
    return Math.floor(this.customer.totalSpend() / 10);
  }
}
